        $this->app->singleton(DocumentTypeRegistry::class);
        $this->app->singleton(DocumentExporterRegistry::class);
        $this->app->singleton(DocumentsManager::class);
        $this->app->bind(NodeDocumentHeads::class, DocumentHeads::class);
