            if (!$drive instanceof Drive || $drive->tenant_id === null) {
                throw NodeNotFoundException::forId('drive');
            }
            $drive = app(TenancyBoundary::class)->assertDrive($drive);
            $row->setAttribute('tenant_id', $drive->tenant_id);
        });
    }
